    "applied_steps_count" INTEGER NOT NULL DEFAULT 0
);

-- 20261126090500_working_inventory_6_stock_l2
DO $m_5e4004a4$
BEGIN
  IF EXISTS (SELECT 1 FROM "_prisma_migrations" WHERE "migration_name" = '20261126090500_working_inventory_6_stock_l2' AND "finished_at" IS NOT NULL) THEN
    RAISE NOTICE 'Skipping 20261126090500_working_inventory_6_stock_l2 (already applied)';
    RETURN;
  END IF;
  EXECUTE $body_5e4004a4$-- Working inventory, part 6 of 10: stock on the shelf at Lansing Steel (L2) (owner, 2026-11-26). Needs parts 1 and 2 first.
-- 971 stocked pieces, 1,219,873 lb of metal and plastic plus supplies counted by the piece. Each piece gets its stock balance and a
-- receipt line in its history dated the day it came in. About 2 in 100 come in on a quality hold, so the hold path can be tested.
-- Nothing is added when the branch is not on file or switched off, or when a tag number is already in use.
-- Refused, with nothing changed, if the books are already started: run this before starting the sandbox books.

DO $guard$
BEGIN
  IF EXISTS (SELECT 1 FROM "AppSetting" WHERE key = 'ledger.activation' AND value->>'active' = 'true') THEN
    RAISE EXCEPTION 'The books are already started, so stock loaded here would not be on them. Nothing was changed.';
  END IF;
END $guard$;

